module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiFlyout,\n  EuiFlyoutBody,\n  EuiFlyoutHeader,\n  EuiButton,\n  EuiText,\n  EuiTitle,\n  EuiFieldText,\n  EuiForm,\n  EuiFormRow,\n  EuiFilePicker,\n  EuiRange,\n  EuiSelect,\n  EuiSpacer,\n} from '../../../../src/components';\n\nexport class FlyoutMaxWidth extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isFlyoutVisible: false,\n      isSwitchChecked: true,\n    };\n\n    this.closeFlyout = this.closeFlyout.bind(this);\n    this.showFlyout = this.showFlyout.bind(this);\n  }\n\n  onSwitchChange = () => {\n    this.setState({\n      isSwitchChecked: !this.state.isSwitchChecked,\n    });\n  };\n\n  closeFlyout() {\n    this.setState({ isFlyoutVisible: false });\n  }\n\n  showFlyout() {\n    this.setState({ isFlyoutVisible: true });\n  }\n\n  render() {\n    let flyout;\n\n    if (this.state.isFlyoutVisible) {\n      flyout = (\n        <EuiFlyout\n          onClose={this.closeFlyout}\n          aria-labelledby=\"flyoutMaxWidthTitle\"\n          maxWidth={448}>\n          <EuiFlyoutHeader hasBorder>\n            <EuiTitle size=\"m\">\n              <h2 id=\"flyoutMaxWidthTitle\">448px wide flyout</h2>\n            </EuiTitle>\n          </EuiFlyoutHeader>\n          <EuiFlyoutBody>\n            <EuiText>\n              <p>\n                In many cases, you&rsquo;ll want to set a custom width\n                that&rsquo;s tailored to your content. In this case, the flyout\n                is an ideal width for form elements.\n              </p>\n            </EuiText>\n\n            <EuiSpacer />\n\n            <EuiForm>\n              <EuiFormRow\n                label=\"Text field\"\n                helpText=\"I am some friendly help text.\">\n                <EuiFieldText name=\"first\" />\n              </EuiFormRow>\n\n              <EuiFormRow label=\"Select (with no initial selection)\">\n                <EuiSelect\n                  hasNoInitialSelection\n                  options={[\n                    { value: 'option_one', text: 'Option one' },\n                    { value: 'option_two', text: 'Option two' },\n                    { value: 'option_three', text: 'Option three' },\n                  ]}\n                />\n              </EuiFormRow>\n\n              <EuiFormRow label=\"File picker\">\n                <EuiFilePicker />\n              </EuiFormRow>\n\n              <EuiFormRow label=\"Range\">\n                <EuiRange min={0} max={100} name=\"range\" id=\"range\" />\n              </EuiFormRow>\n            </EuiForm>\n          </EuiFlyoutBody>\n        </EuiFlyout>\n      );\n    }\n\n    return (\n      <div>\n        <EuiButton onClick={this.showFlyout}>Show max-width flyout</EuiButton>\n\n        {flyout}\n      </div>\n    );\n  }\n}\n"