module.exports = "import React, { Component, Fragment } from 'react';\n\nimport {\n  EuiForm,\n  EuiFormRow,\n  EuiSelect,\n  EuiSpacer,\n} from '../../../../src/components';\nimport {\n  EuiSeriesChart,\n  EuiLineSeries,\n  EuiSeriesChartUtils,\n} from '../../../../src/experimental';\n\nconst {\n  LINEAR,\n  CURVE_CARDINAL,\n  CURVE_NATURAL,\n  CURVE_MONOTONE_X,\n  CURVE_MONOTONE_Y,\n  CURVE_BASIS,\n  CURVE_BUNDLE,\n  CURVE_CATMULL_ROM,\n  CURVE_STEP,\n  CURVE_STEP_AFTER,\n  CURVE_STEP_BEFORE,\n} = EuiSeriesChartUtils.CURVE;\n\nconst DATA_A = [\n  { x: 0, y: 1 },\n  { x: 1, y: 1 },\n  { x: 2, y: 2 },\n  { x: 3, y: -1 },\n  { x: 5, y: 2 },\n];\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.options = [\n      { value: LINEAR, text: 'Linear' },\n      { value: CURVE_CARDINAL, text: 'Curve Cardinal' },\n      { value: CURVE_NATURAL, text: 'Curve Natural' },\n      { value: CURVE_MONOTONE_X, text: 'Curve Monotone X' },\n      { value: CURVE_MONOTONE_Y, text: 'Curve Monotone Y' },\n      { value: CURVE_BASIS, text: 'Curve Basis' },\n      { value: CURVE_BUNDLE, text: 'Curve Bundle' },\n      { value: CURVE_CATMULL_ROM, text: 'Curve Catmull Rom' },\n      { value: CURVE_STEP, text: 'Curve Step' },\n      { value: CURVE_STEP_AFTER, text: 'Curve Step After' },\n      { value: CURVE_STEP_BEFORE, text: 'Curve Step Before' },\n    ];\n\n    this.state = {\n      value: this.options[0].value,\n    };\n  }\n\n  onChange = e => {\n    this.setState({\n      value: e.target.value,\n    });\n  };\n\n  render() {\n    return (\n      <Fragment>\n        <EuiForm>\n          <EuiFormRow label=\"Line Mode\">\n            <EuiSelect\n              options={this.options}\n              value={this.state.value}\n              onChange={this.onChange}\n            />\n          </EuiFormRow>\n        </EuiForm>\n\n        <EuiSpacer size=\"xl\" />\n\n        <EuiSeriesChart width={600} height={200}>\n          <EuiLineSeries\n            name=\"Total Bytes\"\n            data={DATA_A}\n            curve={this.state.value}\n          />\n        </EuiSeriesChart>\n      </Fragment>\n    );\n  }\n}\n"