module.exports = "import React, { Component, Fragment } from 'react';\n\nimport { EuiRange, EuiSpacer, EuiDualRange } from '../../../../src/components';\n\nimport makeId from '../../../../src/components/form/form_row/make_id';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      value: '20',\n      dualValue: [20, 100],\n    };\n  }\n\n  onChange = e => {\n    this.setState({\n      value: e.target.value,\n    });\n  };\n\n  onDualChange = value => {\n    this.setState({\n      dualValue: value,\n    });\n  };\n\n  render() {\n    return (\n      <Fragment>\n        <EuiRange\n          id={makeId()}\n          value={this.state.value}\n          onChange={this.onChange}\n          showInput\n        />\n\n        <EuiSpacer size=\"xl\" />\n\n        <EuiDualRange\n          id={makeId()}\n          value={this.state.dualValue}\n          onChange={this.onDualChange}\n          showInput\n        />\n      </Fragment>\n    );\n  }\n}\n"