module.exports = "import React, { Component, Fragment } from 'react';\n\nimport { EuiSpacer, EuiButton } from '../../../../src/components';\nimport {\n  EuiSeriesChart,\n  EuiBarSeries,\n  EuiSeriesChartUtils,\n} from '../../../../src/experimental';\n\nconst { ORIENTATION, SCALE } = EuiSeriesChartUtils;\n\nconst dataA = [\n  { x: 1, y: 'A' },\n  { x: 2, y: 'B' },\n  { x: 3, y: 'C' },\n  { x: 4, y: 'D' },\n  { x: 5, y: 'E' },\n];\nconst dataB = [\n  { x: 3, y: 'A' },\n  { x: 2, y: 'B' },\n  { x: 1, y: 'C' },\n  { x: 2, y: 'D' },\n  { x: 3, y: 'E' },\n];\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      stacked: true,\n    };\n  }\n\n  onSwitchStacked = () => {\n    this.setState({\n      stacked: !this.state.stacked,\n    });\n  };\n\n  render() {\n    const { stacked } = this.state;\n    return (\n      <Fragment>\n        <EuiButton color=\"primary\" onClick={this.onSwitchStacked}>\n          Toggle stacked\n        </EuiButton>\n        <EuiSpacer size=\"l\" />\n        <EuiSeriesChart\n          width={600}\n          height={200}\n          orientation={ORIENTATION.HORIZONTAL}\n          yType={SCALE.ORDINAL}\n          stackBy={stacked ? 'x' : null}>\n          <EuiBarSeries name={'Tag A'} data={dataA} />\n          <EuiBarSeries name={'Tag B'} data={dataB} />\n        </EuiSeriesChart>\n      </Fragment>\n    );\n  }\n}\n"