module.exports = "import React from 'react';\n\nimport {\n  EuiCard,\n  EuiIcon,\n  EuiFlexGroup,\n  EuiFlexItem,\n} from '../../../../src/components';\n\nexport default () => (\n  <EuiFlexGroup gutterSize=\"l\">\n    <EuiFlexItem>\n      <EuiCard\n        layout=\"horizontal\"\n        icon={<EuiIcon size=\"xxl\" type={'logoBeats'} />}\n        title={'Elastic Beats'}\n        description=\"Example of a card's description. Stick to one or two sentences.\"\n        onClick={() => window.alert('Card clicked')}\n      />\n    </EuiFlexItem>\n    <EuiFlexItem>\n      <EuiCard\n        layout=\"horizontal\"\n        icon={<EuiIcon size=\"xxl\" type={'logoCloud'} />}\n        title={'Elastic Cloud'}\n        description=\"Example of a card's description. Stick to one or two sentences.\"\n        onClick={() => window.alert('Card clicked')}\n      />\n    </EuiFlexItem>\n    <EuiFlexItem>\n      <EuiCard\n        layout=\"horizontal\"\n        title={'No icon example'}\n        description=\"Example of a card's description. Stick to one or two sentences.\"\n        onClick={() => window.alert('Card clicked')}\n      />\n    </EuiFlexItem>\n  </EuiFlexGroup>\n);\n"