module.exports = "import React, { Component } from 'react';\n\nimport { EuiTabs, EuiTab } from '../../../../src/components';\n\nclass EuiTabsExample extends Component {\n  constructor(props) {\n    super(props);\n\n    this.tabs = [\n      {\n        id: 'cobalt',\n        name: 'Cobalt',\n        disabled: false,\n      },\n      {\n        id: 'dextrose',\n        name: 'Dextrose',\n        disabled: false,\n      },\n      {\n        id: 'hydrogen',\n        name: 'Hydrogen',\n        disabled: true,\n      },\n      {\n        id: 'monosodium_glutammate',\n        name: 'Monosodium Glutamate',\n        disabled: false,\n      },\n    ];\n\n    this.state = {\n      selectedTabId: 'cobalt',\n    };\n  }\n\n  onSelectedTabChanged = id => {\n    this.setState({\n      selectedTabId: id,\n    });\n  };\n\n  renderTabs() {\n    return this.tabs.map((tab, index) => (\n      <EuiTab\n        onClick={() => this.onSelectedTabChanged(tab.id)}\n        isSelected={tab.id === this.state.selectedTabId}\n        disabled={tab.disabled}\n        key={index}>\n        {tab.name}\n      </EuiTab>\n    ));\n  }\n\n  render() {\n    return <EuiTabs display=\"condensed\">{this.renderTabs()}</EuiTabs>;\n  }\n}\n\nexport default EuiTabsExample;\n"