module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiButton,\n  EuiButtonEmpty,\n  EuiFieldText,\n  EuiForm,\n  EuiFormRow,\n  EuiModal,\n  EuiModalBody,\n  EuiModalFooter,\n  EuiModalHeader,\n  EuiModalHeaderTitle,\n  EuiOverlayMask,\n  EuiRange,\n  EuiSwitch,\n} from '../../../../src/components';\n\nimport SuperSelectComplexExample from '../super_select/super_select_complex';\n\nimport makeId from '../../../../src/components/form/form_row/make_id';\n\nexport class Modal extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isModalVisible: false,\n      isSwitchChecked: true,\n    };\n\n    this.closeModal = this.closeModal.bind(this);\n    this.showModal = this.showModal.bind(this);\n  }\n\n  onSwitchChange = () => {\n    this.setState({\n      isSwitchChecked: !this.state.isSwitchChecked,\n    });\n  };\n\n  closeModal() {\n    this.setState({ isModalVisible: false });\n  }\n\n  showModal() {\n    this.setState({ isModalVisible: true });\n  }\n\n  render() {\n    const formSample = (\n      <EuiForm>\n        <EuiFormRow>\n          <EuiSwitch\n            id={makeId()}\n            name=\"popswitch\"\n            label=\"Isn't this modal form cool?\"\n            checked={this.state.isSwitchChecked}\n            onChange={this.onSwitchChange}\n          />\n        </EuiFormRow>\n\n        <EuiFormRow label=\"A text field\">\n          <EuiFieldText name=\"popfirst\" />\n        </EuiFormRow>\n\n        <EuiFormRow label=\"Range\" helpText=\"Some help text for the range\">\n          <EuiRange min={0} max={100} name=\"poprange\" />\n        </EuiFormRow>\n\n        <EuiFormRow label=\"A SuperSelect field\">\n          <SuperSelectComplexExample />\n        </EuiFormRow>\n      </EuiForm>\n    );\n\n    let modal;\n\n    if (this.state.isModalVisible) {\n      modal = (\n        <EuiOverlayMask>\n          <EuiModal onClose={this.closeModal} initialFocus=\"[name=popswitch]\">\n            <EuiModalHeader>\n              <EuiModalHeaderTitle>Form in a modal</EuiModalHeaderTitle>\n            </EuiModalHeader>\n\n            <EuiModalBody>{formSample}</EuiModalBody>\n\n            <EuiModalFooter>\n              <EuiButtonEmpty onClick={this.closeModal}>Cancel</EuiButtonEmpty>\n\n              <EuiButton onClick={this.closeModal} fill>\n                Save\n              </EuiButton>\n            </EuiModalFooter>\n          </EuiModal>\n        </EuiOverlayMask>\n      );\n    }\n    return (\n      <div>\n        <EuiButton onClick={this.showModal}>Show Modal</EuiButton>\n\n        {modal}\n      </div>\n    );\n  }\n}\n"